package com.tekwatt.notification.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="notifications")public class Notification{@Id private UUID id;@Column(nullable=false)private UUID tenantId;private UUID userId;@Column(nullable=false,unique=true,length=64)private String idempotencyKey;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private NotificationChannel channel;@Column(nullable=false,length=254)private String recipient;@Column(length=200)private String subject;@Column(nullable=false,columnDefinition="TEXT")private String body;@Column(length=100)private String templateKey;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private NotificationStatus status;@Column(nullable=false)private Integer attemptCount;@Column(nullable=false)private Integer maxAttempts;@Column(length=150)private String providerMessageId;@Column(length=1000)private String lastError;@Column(nullable=false,updatable=false)private Instant createdAt;private Instant sentAt;private Instant nextAttemptAt;@Column(nullable=false)private Instant updatedAt;protected Notification(){}public Notification(UUID t,UUID u,String key,NotificationChannel c,String to,String sub,String body,String template,Integer max){id=UUID.randomUUID();tenantId=t;userId=u;idempotencyKey=key;channel=c;recipient=to;subject=sub;this.body=body;templateKey=template;status=NotificationStatus.QUEUED;attemptCount=0;maxAttempts=max;createdAt=Instant.now();updatedAt=createdAt;}public void sending(){if(attemptCount>=maxAttempts)throw new IllegalStateException("Maximum attempts reached");status=NotificationStatus.SENDING;attemptCount++;updatedAt=Instant.now();}public void sent(String providerId){status=NotificationStatus.SENT;providerMessageId=providerId;lastError=null;sentAt=Instant.now();nextAttemptAt=null;updatedAt=sentAt;}public void failed(String error){status=NotificationStatus.FAILED;lastError=error;updatedAt=Instant.now();}public void retry(){if(attemptCount>=maxAttempts)throw new IllegalStateException("Maximum attempts reached");status=NotificationStatus.QUEUED;nextAttemptAt=Instant.now();updatedAt=nextAttemptAt;}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getUserId(){return userId;}public String getIdempotencyKey(){return idempotencyKey;}public NotificationChannel getChannel(){return channel;}public String getRecipient(){return recipient;}public String getSubject(){return subject;}public String getBody(){return body;}public String getTemplateKey(){return templateKey;}public NotificationStatus getStatus(){return status;}public Integer getAttemptCount(){return attemptCount;}public Integer getMaxAttempts(){return maxAttempts;}public String getProviderMessageId(){return providerMessageId;}public String getLastError(){return lastError;}public Instant getCreatedAt(){return createdAt;}public Instant getSentAt(){return sentAt;}public Instant getNextAttemptAt(){return nextAttemptAt;}public Instant getUpdatedAt(){return updatedAt;}}
